"use client"

import * as React from "react"
import { GlimmScope, type GlimmScopeHandle } from "glimm/react"

const hairline = "rgba(0,0,0,.08)"
const skeleton = "rgba(0,0,0,.07)"
const skeletonHi = "rgba(0,0,0,.13)"
const blue = "#2E70FF"

function Bar({ width, height = 8, hi = false }: { width: number | string; height?: number; hi?: boolean }) {
  return <span aria-hidden="true" style={{ background: hi ? skeletonHi : skeleton, borderRadius: 4, display: "block", height, width }} />
}

function NavRow({ width, active, engaged }: { width: number; active?: boolean; engaged: boolean }) {
  return <div style={{ alignItems: "center", background: active ? engaged ? "rgba(46,112,255,.10)" : "rgba(0,0,0,.04)" : "transparent", borderRadius: 6, display: "flex", gap: 9, margin: "0 -8px", padding: "6px 8px", transition: "background-color 700ms ease" }}><span style={{ background: active && engaged ? "rgba(46,112,255,.45)" : skeleton, borderRadius: 4, height: 14, width: 14 }} /><Bar width={width} /></div>
}

function AutopilotScene() {
  const scope = React.useRef<GlimmScopeHandle>(null)
  const toggle = React.useRef<HTMLButtonElement>(null)
  const [checked, setChecked] = React.useState(false)
  const [engaged, setEngaged] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [used, setUsed] = React.useState(false)

  const run = () => {
    if (busy) return
    const next = !checked
    setChecked(next)
    setBusy(true)
    setUsed(true)
    const rect = toggle.current?.getBoundingClientRect()
    scope.current?.play({
      at: rect ? [rect.left + rect.width / 2, rect.top + rect.height / 2] : undefined,
      anticipate: true,
      onBurst: () => { setEngaged(next); setBusy(false) },
    })
  }

  return <GlimmScope ref={scope} palette="azure" sweepMs={2700} style={{ inset: 0, position: "absolute" }}>
    <main style={{ background: "#fff", color: "#242529", display: "flex", flexDirection: "column", fontFamily: "Inter,ui-sans-serif,system-ui,sans-serif", height: "100%", minHeight: 560, overflow: "hidden" }}>
      <header style={{ alignItems: "center", borderBottom: `1px solid ${hairline}`, display: "flex", height: 54, justifyContent: "space-between", padding: "0 16px" }}><div style={{ alignItems: "center", display: "flex", gap: 12 }}><Bar height={14} hi width={52} /><span style={{ background: hairline, height: 18, width: 1 }} /><Bar width={84} /></div><div style={{ alignItems: "center", display: "flex", gap: 14 }}><Bar width={38} /><Bar width={38} /><span style={{ background: skeletonHi, borderRadius: 999, height: 26, width: 26 }} /></div></header>
      <div style={{ display: "flex", flex: 1, minHeight: 0 }}>
        <aside style={{ borderRight: `1px solid ${hairline}`, flexShrink: 0, overflow: "hidden", padding: "16px 12px", width: 230 }}><Bar width={56} /><div style={{ height: 14 }} />{[[120,false],[96,true],[134,false],[104,false],[88,false]].map(([w,a], i) => <NavRow active={a as boolean} engaged={engaged} key={i} width={w as number} />)}<div style={{ height: 22 }} /><Bar width={42} /><div style={{ height: 14 }} />{[110,128,92].map((w) => <NavRow engaged={engaged} key={w} width={w} />)}</aside>
        <section style={{ background: engaged ? "#F1F4FD" : "#F7F7F8", flex: 1, minWidth: 0, overflow: "auto", padding: "30px 30px 44px", transition: "background-color 700ms ease" }}><div style={{ margin: "0 auto", maxWidth: 760 }}>
          <div style={{ display: "grid", gap: 9 }}><Bar height={17} hi width={150} /><Bar width={238} /></div>
          <div style={{ background: engaged ? "rgba(46,112,255,.06)" : "#fff", borderRadius: 12, boxShadow: `inset 0 0 0 1px ${engaged ? "rgba(46,112,255,.32)" : hairline}`, marginTop: 22, padding: 18, position: "relative", transition: "background-color 700ms ease,box-shadow 700ms ease" }}>
            <div style={{ alignItems: "center", display: "flex", justifyContent: "space-between" }}><div style={{ alignItems: "center", display: "flex", gap: 12 }}><span style={{ background: engaged ? blue : skeleton, borderRadius: 9, height: 38, transition: "background-color 700ms ease", width: 38 }} /><div style={{ display: "grid", gap: 6 }}><Bar height={10} hi width={64} /><span style={{ color: engaged ? blue : "#8c8c91", fontSize: 12, fontWeight: 450 }}>{engaged ? "Engaged" : "Off"}</span></div></div><div style={{ display: "inline-flex", position: "relative" }}><button ref={toggle} aria-label="Autopilot" aria-checked={checked} disabled={busy} onClick={run} role="switch" style={{ background: checked ? "#242529" : "#e7e7e8", border: 0, borderRadius: 999, cursor: busy ? "wait" : "pointer", height: 22, padding: 0, position: "relative", width: 36 }}><span style={{ background: "#fff", borderRadius: 999, boxShadow: "0 1px 2px rgba(0,0,0,.18)", display: "block", height: 18, left: 2, position: "absolute", top: 2, transform: checked ? "translateX(14px)" : "none", transition: "transform 180ms ease", width: 18 }} /></button>{!used && <span aria-hidden="true" style={{ bottom: 34, fontFamily: "cursive", fontSize: 17, left: "50%", position: "absolute", transform: "translateX(-50%) rotate(-2deg)", whiteSpace: "nowrap" }}>Flip the switch ↓</span>}</div></div>
            <div style={{ display: "grid", gap: 8, marginTop: 16 }}><Bar width="100%" /><Bar width="68%" /></div>
          </div>
          <div style={{ display: "flex", gap: 14, marginTop: 20 }}>{[0,1,2].map((i) => <div key={i} style={{ background: "#fff", borderRadius: 10, boxShadow: `inset 0 0 0 1px ${hairline}`, display: "grid", flex: 1, gap: 10, padding: 16 }}><Bar width={62} /><Bar height={18} hi width={84} /><Bar width={46} /></div>)}</div>
          <div style={{ background: "#fff", borderRadius: 10, boxShadow: `inset 0 0 0 1px ${hairline}`, marginTop: 14, padding: 18 }}><Bar height={9} hi width={120} /><div style={{ display: "grid", gap: 13, marginTop: 16 }}>{[[186,110],[150,92],[212,132],[144,100]].map(([a,b]) => <div key={a} style={{ alignItems: "center", display: "flex", gap: 12 }}><span style={{ background: skeleton, borderRadius: 7, height: 28, width: 28 }} /><div style={{ display: "grid", flex: 1, gap: 6 }}><Bar width={a} /><Bar height={6} width={b} /></div><Bar width={44} /></div>)}</div></div>
        </div></section>
      </div>
    </main>
  </GlimmScope>
}

export default function GlimmAutopilot() { return <AutopilotScene /> }
export { GlimmAutopilot }
